  });

  final Widget? title;
  final Widget? description;
  final Widget? action;
  final bool border;

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final pad = _CardScope.of(context);
    return Container(
      padding: EdgeInsets.only(left: pad, right: pad, bottom: border ? pad : 0),
      decoration: border
          ? BoxDecoration(
              border: Border(bottom: BorderSide(color: t.colors.border)),
            )
          : null,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (title != null)
                  Semantics(
                    header: true,
                    child: DefaultTextStyle.merge(
                      style: t.text.base.copyWith(
                        fontWeight: FontWeight.w600,
                        height: 1,
                        // The font's spare leading split above and below, so the text sits centred.
                        leadingDistribution: TextLeadingDistribution.even,
                      ),
                      child: title!,
                    ),
                  ),
                if (title != null && description != null)
                  const SizedBox(height: 6),
                if (description != null)
                  DefaultTextStyle.merge(
                    style: t.text.sm.copyWith(color: t.colors.mutedForeground),
                    child: description!,
                  ),
              ],
            ),
          ),
          if (action != null) ...[const SizedBox(width: 16), action!],
