class _ToastCard extends StatefulWidget {
  const _ToastCard({
    required this.toast,
    required this.host,
    required this.behind,
    required this.frontHeight,
  });

  final _Toast toast;
  final _ToastHost host;

  /// Behind the front card in the stack: only its edge shows.
  final bool behind;
