        ? which
        : '${widget.semanticLabel}, $which';
  }

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    const thumb = 16.0;
    final across = widget.axis == Axis.horizontal;
    final values = _values;
    return LayoutBuilder(
      builder: (context, box) {
        final length = across
