                  for (final (i, v) in values.indexed)
                    along(
                      at(v),
                      thumb,
                      Center(
                        child: _Thumb(
                          enabled: _enabled,
                          dragging: _dragging == i,
                          label: _labelFor(i, values.length),
                          value: _read(v),
                          increased: _read(_snap(v + _keyStep)),
                          decreased: _read(_snap(v - _keyStep)),
                          onStep: (steps) => _set(i, v + steps * _keyStep),
                          onEnd: (top) =>
