        DateTime.now(),
  );
  final _node = FocusNode(debugLabel: 'Calendar');
  bool _keyboard = false;

  static DateTime _monthOf(DateTime d) => DateTime(d.year, d.month);

  @override
  void dispose() {
    _node.dispose();
    super.dispose();
