      child: Semantics(
        container: true,
        label: names.monthYear(_month),
        explicitChildNodes: true,
        child: SizedBox(
          width: 7 * 32,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              SizedBox(
