                    _Nav(
                      icon: AshlarIconsRoundedStroke.chevronRight,
                      label: 'Next month',
                      onPressed: canOn ? () => _showMonth(1) : null,
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 8),
              ExcludeSemantics(
                child: Row(
                  children: [
                    for (var i = 0; i < 7; i++)
